class AgainstPython(unittest.TestCase):
    """Random well-formed expressions must match Python's own int semantics."""
    def test_random(self):
        rng = random.Random(0)
        ops = ["+", "-", "*", "//", "%", "**"]
        def gen(depth):
            r = rng.random()
            if depth == 0 or r < 0.3:
                return str(rng.randint(0, 9))
            if r < 0.4:
                return "(" + gen(depth - 1) + ")"
            if r < 0.5:
                return rng.choice(["-", "+"]) + gen(depth - 1)
            return gen(depth - 1) + " " + rng.choice(ops) + " " + gen(depth - 1)
        checked = 0
        for _ in range(3000):
            s = gen(4)
            try:
                expected = eval(s, {"__builtins__": {}})  # test oracle only
            except (ZeroDivisionError, ValueError):
                with self.assertRaises(ValueError, msg=s): evaluate(s)
                continue
            if isinstance(expected, float) or expected is None:
                continue
            self.assertEqual(evaluate(s), expected, msg=s)
            checked += 1
        self.assertGreater(checked, 1000)


if __name__ == "__main__":
    unittest.main(verbosity=1)
